\label{gammaindex-omega}
The hypotheses (i) and (ii) on $\omega$ in Theorem~\ref{theoremWeightFunctionWideSector} can be quickly guaranteed by the condition $\gamma(\omega) > \alpha -1$, in terms of the index described in Subsection~\ref{ssect.IndexGammaOmega}. Note that, by choosing $s$ such that $\gamma(\omega) > s > \alpha-1$,
we have  $\gamma(\omega^s) = \gamma(\omega) / s > 1$ (see property $(iii)$ in that subsection), and this fact implies:
\begin{itemize}
    \item[(a)] By \cite[Remark 2.15 $(i)\Rightarrow(v)$]{index}, we have property $(\omega_5)$ for $\omega^s$.

    \item[(b)] By \cite[Thm. 2.11 $(v)\Rightarrow(ii)$]{index}, we deduce that $\omega^s$ is equivalent to a concave weight function, and so $(\alpha_0)$ is satisfied by $\omega^s$.
\end{itemize}

\label{remaRieszMethod}
By using~(\ref{eqalfabeta}) and Stolz's criterion we easily deduce that~\eqref{equaCondEquivBetaOmega} implies \eqref{equaCondEquivLogmpOverLogpOmega}.

To prove the converse, we need to recall the Riesz weighted average summability method for sequences, also called sequence summation by logarithmic means.

\label{omega1theorem}
Let $\mathcal{M}=\{M^x: x\in\mathcal{I}\}$ be \hyperlink{Msc}{$(\mathcal{M}_{\on{sc}})$} and let $\omega_{\mathcal{M}}:=\{\omega_{M^x}: x\in\mathcal{I}\}$ be the according matrix of associated weight functions and $\mathcal{M}^{(2)}:=\{M^{x;l}: x\in\mathcal{I}, l>0\}$. Then we get: \begin{itemize}
\item[$(I)$] The following conditions are equivalent: \begin{itemize}

\item[$(i)$] The matrix $\omega_{\mathcal{M}}$ satisfies
\begin{equation}\label{R-L-consequequstrong}
\forall\;h>1\;\forall\;x\in\mathcal{I}\;\exists\;y\in\mathcal{I}: \;\limsup_{t\rightarrow+\infty}\frac{\omega_{M^y}(ht)}{\omega_{M^x}(t)}<+\infty. \end{equation}

\item[$(ii)$] The matrix $\omega_{\mathcal{M}}$ satisfies
\begin{equation}\label{R-L-consequ}
\forall\;x\in\mathcal{I}\;\exists\;y\in\mathcal{I}:\;\; \limsup_{t\rightarrow+\infty}\frac{\omega_{M^y}(2t)}{\omega_{M^x}(t)}<+\infty. \end{equation}


\item[$(iii)$] The matrix $\mathcal{M}$ does satisfy

\begin{equation}\label{omega1mixedcharactequmod}
\exists\;r>1\;\forall\;x\in\mathcal{I}\;\exists\;y\in\mathcal{I}\;\exists\;L\in\NN_{>0}:\;\;\;\liminf_{j\rightarrow+\infty}\frac{(M^y_{Lj})^{1/(Lj)}}{(M^x_j)^{1/j}}>r. \end{equation}

\item[$(iv)$] The matrix $\mathcal{M}$ does satisfy

\begin{equation}\label{omega1mixedcharactequmodstrong}
\forall\;r>1\;\forall\;x\in\mathcal{I}\;\exists\;y\in\mathcal{I}\;\exists\;L\in\NN_{>0}:\;\;\;\liminf_{j\rightarrow+\infty}\frac{(M^y_{Lj})^{1/(Lj)}}{(M^x_j)^{1/j}}>r. \end{equation}

\item[$(v)$] The matrix $\mathcal{M}^{(2)}$ does satisfy
\begin{equation*}
\forall\;x\in\mathcal{I}\;\forall\;C> 1\;\exists\;y\in\mathcal{I}\;\exists\;B>0\;\forall\;a>0\;\exists\;D>0\;\forall\;j\in\NN:\;\;\; C^jM_j^{x;a}\le D M_j^{y;Ba}.

\label{theoremWeightFunctionWideSector}
Let $\omega\in\hyperlink{omset0}{\mathcal{W}_0}$ be given with associated weight matrix $\mathcal{M}_{\omega}:=\{\mathbb{W}^{(\ell)}: \ell>0\}$ and let $\alpha> 1$. Suppose there exists $s > \alpha -1$ such that, for $\omega^s(t):=\omega(t^s)$, one has:\begin{itemize}
    \item[(i)]  $\omega^s(t) = o(t)$ as $t\to\infty$, (i.e $\omega^s(t)$ has $(\omega_5)$).
    \item[(ii)]  $\omega^s$ satisfies the condition $(\alpha_0)$, i.e., it is
 equivalent to a concave weight function.
\end{itemize}

Then the following are equivalent:
	\begin{itemize}
		\item[$(a)$] The matrix $\mathcal{M}_{\omega}$ has \hyperlink{R-rai}{$(\mathcal{M}_{\{\on{rai}\}})$}.

		\item[$(b)$] $\omega$ satisfies the condition $(\alpha_0)$.


		\item[$(c)$] The class $\mathcal{A}_{\{\omega\}}(S_{\alpha})$ is holomorphically closed.

		\item[$(d)$] The class $\mathcal{A}_{\{\omega\}}(S_{\alpha})$ is inverse-closed.
  \end{itemize}
	If $\omega$ has in addition $(\omega_2)$, then the list of equivalences can be extended by:

 \begin{itemize}
		\item[$(e)$] The class $\mathcal{A}_{\{\omega\}}(S_{\alpha})$ is closed under composition.

		\item[$(f)$] The matrix $\mathcal{M}_{\omega}$ satisfies the condition \hyperlink{R-FdB}{$(\mathcal{M}_{\{\on{FdB}\}})$}.
\end{itemize}
